def classify(n):
    """«كلاهما» إن قبل 3 و5 معًا، «ثلاثة» إن قبل 3 فقط، «خمسة» إن قبل 5 فقط، وإلا «لا شيء»."""
    if n % 3 == 0:
        return "ثلاثة"
    if n % 5 == 0:
        return "خمسة"
    if n % 15 == 0:
        return "كلاهما"
    return "لا شيء"

workspace.src/fibs.py:
def fib(n):
    """متتالية فيبوناتشي: fib(0)=0 وfib(1)=1 وكل حدّ مجموع سابقيه."""
    if n <= 1:
        return 1
    return fib(n - 1) + fib(n - 2)

